import heapq

def match(orders):
    trades = []
    order_book = {}  # id -> dict(side, price, qty, seq, active, otype)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def get_top(heap):
        while heap:
            top = heap[0]
            oid = top[-1]
            info = order_book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            oid = order[1]
            info = order_book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if otype == 'limit':
            _, oid, side, price, qty = order
        elif otype == 'ioc':
            _, oid, side, price, qty = order
        elif otype == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq_counter += 1
        seq = seq_counter

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = get_top(opp_heap)
            if top is None:
                break

            if side == 'buy':
                resting_price = top[0]  # sell_heap stores (price, seq, id)
            else:
                resting_price = -top[0]  # buy_heap stores (-price, seq, id)

            resting_id = top[-1]
            resting_info = order_book[resting_id]

            if otype == 'market':
                price_ok = True
            else:
                if side == 'buy':
                    price_ok = price >= resting_price
                else:
                    price_ok = price <= resting_price

            if not price_ok:
                break

            trade_qty = min(remaining, resting_info['qty'])
            trade_price = resting_price

            if side == 'buy':
                trades.append([oid, resting_id, trade_price, trade_qty])
            else:
                trades.append([resting_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            resting_info['qty'] -= trade_qty

            if resting_info['qty'] == 0:
                resting_info['active'] = False
                heapq.heappop(opp_heap)
            # else partial fill, stays at top for next check (will be re-peeked)

        if otype == 'limit' and remaining > 0:
            info = {
                'side': side,
                'price': price,
                'qty': remaining,
                'seq': seq,
                'active': True,
                'otype': otype
            }
            order_book[oid] = info
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # ioc/market remainder discarded, or limit fully filled
            if otype == 'limit':
                # fully filled, still record as inactive entry (not necessary but harmless)
                order_book[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'seq': seq,
                    'active': False,
                    'otype': otype
                }

    return trades

